def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h - 2, 3):
        row = []
        for c in range(0, w - 2, 3):
            counts = {}
            for i in range(r, r + 3):
                for j in range(c, c + 3):
                    v = grid[i][j]
                    if v not in (0, 5):
                        counts[v] = counts.get(v, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 0)
        out.append(row)
    return out
